                    onChange={(e) => set(f.name, e.target.value)}
                  />
                )}
                {f.type === "color" && (
                  <input
                    type="color"
                    aria-label={f.label}
                    value={String(values[f.name])}
                    onChange={(e) => set(f.name, e.target.value)}
                  />
                )}
                {f.type === "checkbox" && (
                  <input
                    type="checkbox"
                    aria-label="Toggle"
                    checked={Boolean(values[f.name])}
                    onChange={(e) => set(f.name, e.target.checked)}
                  />
                )}
                {f.type === "select" && (
                  <select
                    aria-label={f.label}
                    value={String(values[f.name])}
                    onChange={(e) => set(f.name, e.target.value)}
                  >
                    {(f.options ?? []).map((o) => (
                      <option key={o.value} value={o.value}>
                        {o.label}
                      </option>
                    ))}
                  </select>
                )}
                {f.type === "radio" && (
                  <div className="mp-radio-group bordered" role="radiogroup" aria-label={f.label}>
                    {(f.options ?? []).map((o) => (
                      <label key={o.value}>
                        <input
                          type="radio"
                          name={f.name}
                          checked={values[f.name] === o.value}
                          onChange={() => set(f.name, o.value)}
                        />
                        {o.label}
                      </label>
                    ))}
                  </div>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <footer>
        <button type="button" className="mp-dialog-btn" onClick={submit}>
          Ok
        </button>
        <button type="button" className="mp-dialog-btn" onClick={editor.closeDialog}>
          Cancel
        </button>
      </footer>
    </>
  );
}

