  await page.waitForTimeout(200);
  await page.screenshot({ path: '.playwright-mcp/shape-test.png', scale: 'css' });
  // also test undo
  await page.keyboard.press('Control+z');
  await page.waitForTimeout(200);
  await page.screenshot({ path: '.playwright-mcp/undo-test.png', scale: 'css' });
  return 'ok';
}

