38	  const c = v * s;
39	  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
40	  const m = v - c;
41	  let r = 0,
42	    g = 0,
43	    b = 0;
44	  if (h < 60) [r, g, b] = [c, x, 0];
45	  else if (h < 120) [r, g, b] = [x, c, 0];
46	  else if (h < 180) [r, g, b] = [0, c, x];
47	  else if (h < 240) [r, g, b] = [0, x, c];
48	  else if (h < 300) [r, g, b] = [x, 0, c];
49	  else [r, g, b] = [c, 0, x];
50	  return { r: (r + m) * 255, g: (g + m) * 255, b: (b + m) * 255 };
51	}
