  const sleep = (ms) => new Promise(r=>setTimeout(r,ms));
  const out = {};
  const tools = ['select','selection','brush','pencil','pick_color','erase','magic_erase','fill','media','text','gradient','clone','crop','blur','sharpen','desaturate','bulge_pinch','animation'];
  for (const t of tools) {
    const el = document.querySelector('.sidebar_left .item.'+t);
    if (!el) { out[t] = 'MISSING'; continue; }
    el.click();
    await sleep(60);
    const attr = document.querySelector('#action_attributes');
    out[t] = attr ? attr.textContent.replace(/\s+/g,' ').trim().replace(/Increase|Decrease/g,'').trim() : null;
    // close any popup
    const close = document.querySelector('.popup button.close, [data-id=popup_close]');
    if (close && close.offsetParent) close.click();
    await sleep(40);
  }
  return out;
}

