async (page) => {
  const errors = [];
  page.on('console', m => { if (m.type()==='error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push('pageerror: '+e.message));
  const log = [];
  // 1) shape picker
  await page.locator('button[title="Shapes (H)"]').click();
  await page.waitForTimeout(200);
  log.push('shapes cells: ' + await page.locator('.mp-shape-cell').count());
  await page.locator('.mp-shape-cell').nth(2).click();
  await page.locator('.mp-popup button:has-text("Ok")').click();
  await page.waitForTimeout(200);
  // 2) draw star shape
  const c = page.locator('.mp-canvas-stage canvas');
  let box = await c.boundingBox();
  await page.mouse.move(box.x + 80, box.y + 70);
  await page.mouse.down();
  await page.mouse.move(box.x + 220, box.y + 210, { steps: 6 });
  await page.mouse.up();
  await page.waitForTimeout(200);
  // 3) fill tool
  await page.locator('button[title="Fill"]').click();
  await page.mouse.click(box.x + 400, box.y + 300);
  await page.waitForTimeout(200);
  // 4) undo
  await page.keyboard.press('Control+z');
  await page.waitForTimeout(200);
  // 5) new layer
  await page.locator('button[title="New layer"]').click();
  await page.waitForTimeout(200);
  log.push('layers: ' + await page.locator('.mp-layer-row').count());
  // 6) new file dialog
  await page.locator('.mp-menu-title:has-text("File")').click();
  await page.locator('.mp-menu-item:has-text("New")').first().click();
  await page.waitForTimeout(200);
  log.push('new dialog open: ' + await page.locator('div[role=dialog]').count());
  await page.locator('.mp-dialog-btn:has-text("Cancel")').click();
  await page.waitForTimeout(150);
  await page.screenshot({ path: '.playwright-mcp/final-test.png', scale: 'css' });
  return JSON.stringify({ errors, log });
}

